mapper.select:
DECLARE @ERROR_GB VARCHAR(20) = NULL , @OUT_RESULT_MSG VARCHAR(1000) = NULL , @STD_COLS VARCHAR(MAX) = NULL , @LOGMSG VARCHAR(MAX) = NULL , @OCCUR_DATE VARCHAR(20) = NULL;
DECLARE @TBL TABLE( DANGA NUMERIC(10,0) , TRANSPORTKUMAK NUMERIC(15,0) );
BEGIN TRY BEGIN TRAN
SELECT @STD_COLS = A1.J_DATE + '/' + A1.KERATYPE + '/' + ISNULL(CASE A1.KERATYPE WHEN '입고' THEN A1.MAIPCHER WHEN '출고' THEN A1.J_COMPANY END,'') + '/순번:'+ ISNULL(CONVERT(VARCHAR,A1.SUN),'') + '/차번' + A1.J_BNUM + '/' + B1.GUBUN1 FROM MESURING A1 LEFT JOIN JAJAE B1 ON A1.J_SERIAL = B1.J_SERIAL WHERE A1.JUNPYOID = #{item.JUNPYOID};
DELETE FROM @TBL;
INSERT INTO @TBL(DANGA, TRANSPORTKUMAK) SELECT CASE WHEN IDANGA != #{item.DANGA} THEN IDANGA ELSE NULL END AS DANGA , CASE WHEN TRANSPORTKUMAK != #{item.TRANSPORTKUMAK} THEN TRANSPORTKUMAK ELSE NULL END AS TRANSPORTKUMAK FROM MESURING WHERE JUNPYOID = #{item.JUNPYOID};
SELECT @LOGMSG = STUFF((CASE WHEN DANGA IS NOT NULL THEN ' | 적용단가 : '+ CONVERT(VARCHAR,DANGA) + ' ▶ ' + CONVERT(VARCHAR,#{item.DANGA}) ELSE '' END) + (CASE WHEN TRANSPORTKUMAK IS NOT NULL THEN ' | 운반비 : ' + CONVERT(VARCHAR,TRANSPORTKUMAK) + ' ▶ ' + CONVERT(VARCHAR,#{item.TRANSPORTKUMAK}) ELSE '' END),1,3,'') FROM @TBL
UPDATE MESURING SET IDANGA = TRY_CONVERT(NUMERIC,#{item.DANGA}) , TRANSPORTKUMAK = TRY_CONVERT(NUMERIC,#{item.TRANSPORTKUMAK}) , IKONGKEP = TRY_CONVERT(NUMERIC,#{item.DANGA}) * TRY_CONVERT(NUMERIC,#{item.WEIGHT}) , UNIT_PRC_CHG_YN = 'Y' , EDIT_GB = 'C' WHERE JUNPYOID = #{item.JUNPYOID};
INSERT INTO @TBL(DANGA, TRANSPORTKUMAK) SELECT CASE WHEN ODANGA != #{item.DANGA} THEN ODANGA ELSE NULL END AS DANGA , CASE WHEN TRANSPORTKUMAK != #{item.TRANSPORTKUMAK} THEN TRANSPORTKUMAK ELSE NULL END AS TRANSPORTKUMAK FROM MESURING WHERE JUNPYOID = #{item.JUNPYOID};
SELECT @LOGMSG = STUFF((CASE WHEN DANGA IS NOT NULL THEN ' | 적용단가 : '+ CONVERT(VARCHAR,DANGA) + ' ▶ ' + CONVERT(VARCHAR,#{item.DANGA}) ELSE '' END) + (CASE WHEN TRANSPORTKUMAK IS NOT NULL THEN ' | 운반비 : ' + CONVERT(VARCHAR,TRANSPORTKUMAK) + ' ▶ ' + CONVERT(VARCHAR,#{item.TRANSPORTKUMAK}) ELSE '' END),1,3,'') FROM @TBL
UPDATE MESURING SET ODANGA = TRY_CONVERT(NUMERIC,#{item.DANGA}) , TRANSPORTKUMAK = TRY_CONVERT(NUMERIC,#{item.TRANSPORTKUMAK}) , OKONGKEP = TRY_CONVERT(NUMERIC,#{item.DANGA}) * TRY_CONVERT(NUMERIC,#{item.WEIGHT}) , UNIT_PRC_CHG_YN = 'Y' , EDIT_GB = 'C' WHERE JUNPYOID = #{item.JUNPYOID};
SELECT @OCCUR_DATE = CONVERT(VARCHAR(20), GETDATE(),20);
INSERT INTO ZSYS_LOG ( OCCUR_DATE , USRCD , LOG_SEQ , EDIT_KIND , PGM_ID , ACS_IP , STD_COLS , REF_RMK , EDIT_RMK ) VALUES( @OCCUR_DATE , #{item.USRCD} , ( SELECT ISNULL(MAX(X1.LOG_SEQ), 0) + 1 FROM ZSYS_LOG X1 WHERE X1.OCCUR_DATE = @OCCUR_DATE AND X1.USRCD = #{item.USRCD}) , 'U' , 'priceInput' , #{item.ACS_IP} , @STD_COLS , 'TABLE : MESURING / JUNPYOID : '+ CONVERT(VARCHAR,#{item.JUNPYOID}) , @LOGMSG )
SET @ERROR_GB = CONVERT(VARCHAR,@@ROWCOUNT); SET @OUT_RESULT_MSG = '저장이 완료되었습니다.'; COMMIT TRAN;
END TRY
BEGIN CATCH ROLLBACK TRAN; SET @ERROR_GB = '-1'; SET @OUT_RESULT_MSG = CONCAT( '오류 메시지 : ', ERROR_MESSAGE() , '\r\n줄번호 : ', ERROR_LINE() , '\r\n오류번호 : ', ERROR_NUMBER() , '\r\n상태코드 : ', ERROR_STATE() , '\r\n프로시저명 : ', ERROR_PROCEDURE() , '\r\n심각도 : ', ERROR_SEVERITY() , '\r\n오류줄번호 : ', @@ERROR);
END CATCH
IF @ERROR_GB = '0' BEGIN SELECT @ERROR_GB AS RESULT , '저장된 건이 없습니다.' AS MSG END ELSE BEGIN SELECT @ERROR_GB AS RESULT , @OUT_RESULT_MSG AS MSG END
